    <a class="skip-link" href="#main-content">Skip to main content</a>
    <div id="root"></div>

    <script>
      const notificationOptions = [
        { id: "notification-email", label: "Email", value: "email" },
        { id: "notification-sms", label: "SMS", value: "sms" },
        {
          id: "notification-push",
          label: "Push Notifications",
          value: "push-notifications"
        }
      ];

      function RadioOption({ id, label, value }) {
        return `
          <div class="radio-option">
            <input id="${id}" type="radio" name="notificationPreference" value="${value}" required>
            <label for="${id}">${label}</label>
          </div>
        `;
      }

      function NotificationPreferenceForm() {
        return `
          <form id="notification-form" novalidate>
            <p class="required-note"><span class="required-marker" aria-hidden="true">*</span> Required field</p>
            <div class="form-field">
              <fieldset aria-describedby="notification-help notification-error">
                <legend>
                  How do you prefer to receive notifications?
                  <span class="required-marker" aria-hidden="true">*</span>
                </legend>
                <p id="notification-help" class="field-help">Choose one notification channel.</p>
                <p id="notification-error" class="field-error" hidden></p>
                <div class="radio-list">
                  ${notificationOptions.map(RadioOption).join("")}
                </div>
              </fieldset>
            </div>
            <div class="actions">
              <button type="submit">Save preference</button>
              <p id="form-status" class="status" aria-live="polite"></p>
            </div>
          </form>
        `;
      }

      function App() {
        return `
          <main id="main-content" class="page-shell">
            <section class="card" aria-labelledby="page-title">
              <p class="eyebrow">Preferences</p>
              <h1 id="page-title">Notification settings</h1>
              <p class="lede">
                Pick the channel that works best for timely product updates and account alerts.
              </p>
              ${NotificationPreferenceForm()}
            </section>
          </main>
        `;
      }

      document.getElementById("root").innerHTML = App();

      document.getElementById("notification-form").addEventListener("submit", (event) => {
        event.preventDefault();
        const form = event.currentTarget;
        const status = document.getElementById("form-status");
        const error = document.getElementById("notification-error");
        const selected = form.querySelector('input[name="notificationPreference"]:checked');
        const radios = form.querySelectorAll('input[name="notificationPreference"]');

        if (!selected) {
          error.hidden = false;
          error.textContent = "Error: Choose how you prefer to receive notifications.";
          radios.forEach((radio) => radio.setAttribute("aria-invalid", "true"));
          status.textContent = "";
          form.querySelector('input[name="notificationPreference"]').focus();
          return;
        }

        error.hidden = true;
        error.textContent = "";
        radios.forEach((radio) => radio.removeAttribute("aria-invalid"));
        status.textContent = "Preference saved.";
      });

      document.getElementById("notification-form").addEventListener("change", (event) => {
        if (event.target.name !== "notificationPreference") {
          return;
        }

        const form = event.currentTarget;
        const error = document.getElementById("notification-error");
        error.hidden = true;
        error.textContent = "";
        form
          .querySelectorAll('input[name="notificationPreference"]')
          .forEach((radio) => radio.removeAttribute("aria-invalid"));
      });
    </script>
